response_schema_definition:
{
  "status": "string (REQUIRED, but flexible (Since these are only for metrics and data collection, They just need to make sense). Enum: SUCCESS | EXECUTING | ERROR | FAILED | STOPPED | PENDING | IN_PROGRESS)",
  "thoughts": [
    {
      "type": "string (REQUIRED, Enum: PLAN | OBSERVATION | AXIOM | QUESTION | HYPOTHESIS | CRITIQUE | ASSUMPTION | GOAL | NORM | DECISION | LONG_TERM | SHORT_TERM | REFLECTION| or a better suitable type)",
      "content": "string (REQUIRED, The textual content of the thought. This should be a clear, concise statement of the agent's reasoning or plan.)"
    } // make sure to stack and scale these. Not a joke, espetially behavioral, habitual and psychological cues. As they may be stored and help refine the system later on.
  ],
  "actions": [ // maybe they could have internals (this->subAction(params), action->output/input ...)
    {
      "action": "string (REQUIRED, Name of the tool, script, or internal function to execute.)",
      "type": "string (REQUIRED, Enum: tool | script | internal )",
      "params": "object (REQUIRED, structure depends on the action, e.g., for 'bash': {'command': 'ls'})",
      "confidence": "float (OPTIONAL, 0.0-1.0)",
      "warnings": ["string (OPTIONAL)"]
    }
  ],
  "stop": "boolean (REQUIRED, Indicates if the agent should stop execution. True if the agent has enough information to respond, false if it needs to continue executing/contemplating actions. This is Mandatory.)",
  "response": "string | null (REQUIRED, User-facing response, or null if actions are pending.)"
}

action_definition.description_text:
Executes a specified Python 3 script. The target script is identified by 'script_path' (relative to a secure, predefined scripts directory). Parameters defined in 'script_params' are passed to the target script as a single JSON string argument. The target script should parse this JSON string to access its parameters. Output from the script's stdout is returned. Parameters: {
  "script_path": "string (REQUIRED, e.g., 'utils/data_converter.py', 'reporting/generate_summary.py')",
  "script_params": "object (OPTIONAL, JSON object of parameters for the target script)"
}

past_conversation_item.content:
{
  "status": "EXECUTING",
  "thoughts": [
    {
      "type": "PLAN",
      "content": "I need to create a new note summarizing the Himothy Covenant. I will use the 'bash' tool to create a new file and add the summary to it."
    },
    {
      "type": "PLAN",
      "content": "First, I will create an empty file named 'himothy_covenant_summary.md' in the notes directory."
    },
    {
      "type": "PLAN",
      "content": "Then, I will add the summary content to the file."
    },
    {
      "type": "DECISION",
      "content": "I will use bash to create the file since it's a simple file creation task."
    }
  ],
  "actions": [
    {
      "action": "bash",
      "type": "tool",
      "params": {
        "command": "touch /home/mlamkadm/notes/himothy_covenant_summary.md"
      },
      "confidence": 0.95,
      "warnings": []
    }
  ],
  "stop": false,
  "response": "Creating a new note file: himothy_covenant_summary.md"
}

{
  "status": "EXECUTING",
  "thoughts": [
    {
      "type": "PLAN",
      "content": "Now that the file 'himothy_covenant_summary.md' has been created, I need to add the summary content to it. Since I don't have the content of the Himothy Covenant, I will ask the Master (Demurge) for it."
    },
    {
      "type": "QUESTION",
      "content": "I need the content for the Himothy Covenant summary from the Master (Demurge)."
    },
    {
      "type": "DECISION",
      "content": "I will use the 'call_subagent' tool to ask the Master (Demurge) for the summary content."
    }
  ],
  "actions": [
    {
      "action": "call_subagent",
      "type": "internal",
      "params": {
        "agent_name": "demurge",
        "prompt": "Please provide the content for the Himothy Covenant summary. I have already created the file 'himothy_covenant_summary.md'."
      },
      "confidence": 0.95,
      "warnings": []
    }
  ],
  "stop": false,
  "response": "Requesting the content for the Himothy Covenant summary from the Master (Demurge)."
}

{
  "status": "ERROR",
  "thoughts": [
    {
      "type": "OBSERVATION",
      "content": "The 'call_subagent' tool failed because the sub-agent 'demurge' was not found. This indicates an issue with the agent registry or configuration."
    },
    {
      "type": "PLAN",
      "content": "Since I cannot directly call 'demurge', I need to find an alternative way to obtain the summary of the Himothy Covenant. I will try to use the 'bash' tool to search for a file containing the summary within the notes directory."
    },
    {
      "type": "HYPOTHESIS",
      "content": "There might be a pre-existing note containing the Himothy Covenant summary."
    },
    {
      "type": "DECISION",
      "content": "I will use the 'bash' tool with the 'grep' command to search for 'Himothy Covenant' in all files within the notes directory."
    }
  ],
  "actions": [
    {
      "action": "bash",
      "type": "tool",
      "params": {
        "command": "grep -r \"Himothy Covenant\" /home/mlamkadm/notes"
      },
      "confidence": 0.8,
      "warnings": [
        "This search might take a while depending on the number of files in the notes directory."
      ]
    }
  ],
  "stop": false,
  "response": "Attempting to locate the Himothy Covenant summary by searching existing notes."
}

{
  "status": "EXECUTING",
  "thoughts": [
    {
      "type": "PLAN",
      "content": "I attempted to call the 'demurge' sub-agent but it failed. Now I'm searching for existing notes containing 'Himothy Covenant'. I will wait for the results of the 'grep' command."
    },
    {
      "type": "OBSERVATION",
      "content": "The 'grep' command is running to search for the Himothy Covenant in existing notes."
    }
  ],
  "actions": [],
  "stop": false,
  "response": "Awaiting results from the search for existing notes containing 'Himothy Covenant'."
}

{
  "status": "EXECUTING",
  "thoughts": [
    {
      "type": "OBSERVATION",
      "content": "Still waiting for the results of the 'grep' command to search for the Himothy Covenant in existing notes."
    },
    {
      "type": "PLAN",
      "content": "Once the 'grep' command finishes, I will analyze the output. If a note is found, I will extract the relevant summary. If no note is found, I will inform the user that I couldn't find the summary and request further instructions."
    }
  ],
  "actions": [],
  "stop": false,
  "response": "Still awaiting results from the search for existing notes containing 'Himothy Covenant'."
